/// <summary>
///     Data provider class for <c>AVASalesRouteCardReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Data provider class for the <c>AVASalesRouteCardReport</c> SSRS Report.
/// </remarks>
[
    //SRSReportQueryAttribute(queryStr(InventTransfer)),
    SRSReportParameterAttribute(classStr(AVAInventTransferJourContract))
]
class AVAInventTransferJourDP extends SrsReportDataProviderPreProcess //SRSReportDataProviderBase
{
    AVAInventTransferShipHeaderTmp  clsHeaderTmp;
    AVAInventTransferShipHeaderTmp  clsHeaderTmpBase;
    AVAInventTransferShipDetailTmp  clsDetailTmp;
    AVAInventTransferShipDetailTmp  clsDetailTmpBase;

    CompanyInfo                     clsCompanyInfo;
    CompanyImage                    clsCompanyLogo;
    Bitmap                          clsCompanyLogoBitmap;
    container                       clsAllBPCompanies;
    SysDocuBrandDetails             clsSysDocuBrandDetails;
    Bitmap                          clsCompanyFooterBitmap;


    InventTransferJour              clsInventTransferJour;
    InventTransferJourLine          clsInventTransferJourLine;
    InventDim                       clsInventDim;

    AVAInventTransferJourContract   clsAVAInventTransferJourContract;
    RefRecId                        clsInventTransferJourRecId;
    RefRecId                        clsInventTransferJourRecIdPrevious;
    InventTransferId                clsInventTransferId;
    InventTransferVoucherId         clsInventTransferVoucherId;
    InventTransferUpdateType        clsInventTransferUpdateType;
    boolean                         clsSingleMode;
    boolean                         clsHeaderCreated;

    UnitOfMeasure                   clsUnitOfMeasurePieces;
    UnitOfMeasure                   clsUnitOfMeasureKilograms;
    UnitOfMeasureConverter_Product  clsUnitOfMeasureConverter_Product;

    int                             clsAdditionalInfoLevel;

    Map                             clsITJLMap;
    MapEnumerator                   clsITJLMapEnumerator;


}

