    clsDetailTmp.PdsCWQtyReceived               = clsInventTransferJourLine.PdsCWQtyReceived;
    clsDetailTmp.PdsCWQtyScrapped               = clsInventTransferJourLine.PdsCWQtyScrapped;
    clsDetailTmp.PdsCWQtyShipped                = clsInventTransferJourLine.PdsCWQtyShipped; 
    // 2009: report method KCS_ItemWeight()
    // return element.KCS_ItemNetWeight(inventTable, InventTransferJourLine.QtyShipped, inventTable.inventTableModuleInvent().UnitId);
    // ItemNetWeight KCS_ItemNetWeight(InventTable     _inventTable, Qty             _qty, SalesUnit       _unit)
    // ret = UnitConvert::valueConvert((_inventTable.NetWeight * _qty), unitParameters.unitIdWeight, unitParameters.unitIDKg, _inventTable.ItemId);
    clsDetailTmp.Port                           = clsInventTransferJourLine.Port;
    clsDetailTmp.QtyReceived                    = clsInventTransferJourLine.QtyReceived;
    clsDetailTmp.QtyScrapped                    = clsInventTransferJourLine.QtyScrapped;
    clsDetailTmp.QtyShipped                     = clsInventTransferJourLine.QtyShipped;
    clsDetailTmp.StatisticalValue               = clsInventTransferJourLine.StatisticalValue;
    clsDetailTmp.StatProcId                     = clsInventTransferJourLine.StatProcId;
    clsDetailTmp.TransactionCode                = clsInventTransferJourLine.TransactionCode;
    clsDetailTmp.TransDate                      = clsInventTransferJourLine.TransDate;
    clsDetailTmp.TransferId                     = clsInventTransferJourLine.TransferId;
    clsDetailTmp.Transport                      = clsInventTransferJourLine.Transport;
    clsDetailTmp.UnitId                         = clsInventTransferJourLine.UnitId;
    clsDetailTmp.UnitPrice                      = clsInventTransferJourLine.UnitPrice;
    //InventDim
    clsDetailTmp.ConfigId                       = clsInventDim.ConfigId;
    clsDetailTmp.inventBatchId                  = clsInventDim.inventBatchId;
    clsDetailTmp.InventColorId                  = clsInventDim.InventColorId;
    clsDetailTmp.InventLocationId               = clsInventDim.InventLocationId;
    clsDetailTmp.InventSerialId                 = clsInventDim.InventSerialId;
    clsDetailTmp.InventSiteId                   = clsInventDim.InventSiteId;
    clsDetailTmp.InventSizeId                   = clsInventDim.InventSizeId;
    clsDetailTmp.InventStatusId                 = clsInventDim.InventStatusId;
    clsDetailTmp.InventStyleId                  = clsInventDim.InventStyleId;
    clsDetailTmp.InventVersionId                = clsInventDim.InventVersionId;
    clsDetailTmp.LicensePlateId                 = clsInventDim.LicensePlateId;
    clsDetailTmp.wMSLocationId                  = clsInventDim.wMSLocationId;
    clsDetailTmp.wMSPalletId                    = clsInventDim.wMSPalletId;
    //AVA fields    
    clsDetailTmp.AVAItemSet                     = clsInventTransferJourLine.AVAItemSet;
    clsDetailTmp.AVAItemSetCompQtyPerSerie      = clsInventTransferJourLine.AVAItemSetCompQtyPerSerie;
    clsDetailTmp.AVAItemSetComponent            = clsInventTransferJourLine.AVAItemSetComponent;
    clsDetailTmp.AVAItemSetExpanded             = clsInventTransferJourLine.AVAItemSetExpanded;
    clsDetailTmp.AVAItemSetParent               = clsInventTransferJourLine.AVAItemSetParent;
    clsDetailTmp.AVAItemSetSerie                = clsInventTransferJourLine.AVAItemSetSerie;
    clsDetailTmp.AVAProdSchedDate               = clsInventTransferJourLine.AVAProdSchedDate;
    clsDetailTmp.KCS_SOCPickingReleaseIndicator = clsInventTransferJourLine.KCS_SOCPickingReleaseIndicator;
    //FurtherPostingType fields
    clsDetailTmp.QtyRemainReceive               = locInventTransferLine.QtyRemainReceive;
    clsDetailTmp.QtyRemainShip                  = locInventTransferLine.QtyRemainShip; // 2009: InventTransferJourLine.KCS_QtyRemainShip missing field
    clsDetailTmp.KCS_ModelNumber                = locNDXModelNumberHandler.nDXModelNumberFromItemId(clsDetailTmp.ItemId); // ToDo: KCS_ModelNumber?     //@NDXBase:NDXModelNumber
    /* No UoM conversion planned
    if(     clsUnitOfMeasureKilograms.RecId
        &&  UnitOfMeasure::unitOfMeasureIdBySymbol(locInventTransferLine.UnitId) == clsUnitOfMeasureKilograms.RecId )
    {
        // already kilograms
        clsDetailTmp.PdsCWQtyShipped            = clsInventTransferJourLine.QtyShipped;
    }
    else if(    clsUnitOfMeasureKilograms.RecId
            &&  UnitOfMeasure::unitOfMeasureIdBySymbol(locInventTransferLine.UnitId) != clsUnitOfMeasureKilograms.RecId )
    {
        clsDetailTmp.PdsCWQtyShipped            = this.convertToKilograms(clsInventTransferJourLine);
    }
    */
    clsDetailTmp.PdsCWQtyShipped                = clsInventTransferJourLine.QtyShipped * locInventTable.NetWeight;


    clsDetailTmp.insert();
    clsAdditionalInfoLevel++;
    /*
    // insert partitioner
    this.initDetailTmp(AVAReportLineType::Partitioner, clsAdditionalInfoLevel);
    clsDetailTmp.insert();
    clsAdditionalInfoLevel++;
    */
}

/// <summary>
///    AVA <c>insertTmpTableDataDetailItemSet</c> method.
/// </summary>
public void insertTmpTableDataDetailItemSet()
{
    InventTransferLine      locInventTransferLineItemSet;
    NDXModelNumberHandler   locNDXModelNumberHandler;
    InventTable             locInventTable;
    InventDim               locInventDim;

    locInventTransferLineItemSet = InventTransferLine::findTransIdShip(clsInventTransferJourLine.inventTransferLine().AVAItemSetParent);


    locNDXModelNumberHandler    = NDXModelNumberHandler::construct();
    locInventTable              = InventTable::find(locInventTransferLineItemSet.ItemId);
    locInventDim                = InventDim::find(locInventTransferLineItemSet.InventDimId);

    this.initDetailTmp(AVAReportLineType::DetailLine, clsAdditionalInfoLevel);

    clsDetailTmp.AmountValue                    = locInventTransferLineItemSet.AmountValue;
    clsDetailTmp.IntrastatCommodity             = locInventTransferLineItemSet.IntrastatCommodity;
    //clsDetailTmp.IntrastatDispatch              = locInventTransferLineItemSet.IntrastatDispatch;
    clsDetailTmp.InventDimId                    = locInventTransferLineItemSet.InventDimId;
    clsDetailTmp.InventTransId                  = locInventTransferLineItemSet.InventTransId;
    //clsDetailTmp.InventTransIdTransit           = locInventTransferLineItemSet.InventTransIdTransit;
    clsDetailTmp.ItemId                         = locInventTransferLineItemSet.ItemId;
    clsDetailTmp.ItemName                       = locInventTable.itemName(InventDim::find(clsDetailTmp.InventDimId));
    clsDetailTmp.LineNum                        = locInventTransferLineItemSet.LineNum;
    clsDetailTmp.OrigCountryRegionId            = locInventTransferLineItemSet.OrigCountryRegionId;
    clsDetailTmp.OrigCountyId                   = locInventTransferLineItemSet.OrigCountyId;
    clsDetailTmp.OrigStateId                    = locInventTransferLineItemSet.OrigStateId;
    clsDetailTmp.PackedExtensions               = locInventTransferLineItemSet.PackedExtensions;
    //clsDetailTmp.ParmId                         = locInventTransferLineItemSet.ParmId;
    clsDetailTmp.PdsCWQtyReceived               = locInventTransferLineItemSet.PdsCWQtyReceived;
    clsDetailTmp.PdsCWQtyScrapped               = locInventTransferLineItemSet.PdsCWQtyScrapped;
    clsDetailTmp.PdsCWQtyShipped                = locInventTransferLineItemSet.PdsCWQtyShipped;
    clsDetailTmp.Port                           = locInventTransferLineItemSet.Port;
    clsDetailTmp.QtyReceived                    = locInventTransferLineItemSet.QtyReceived;
    clsDetailTmp.QtyScrapped                    = locInventTransferLineItemSet.QtyScrapped;
    clsDetailTmp.QtyShipped                     = locInventTransferLineItemSet.QtyShipped;
    clsDetailTmp.StatisticalValue               = locInventTransferLineItemSet.StatisticalValue;
    clsDetailTmp.StatProcId                     = locInventTransferLineItemSet.StatProcId;
    clsDetailTmp.TransactionCode                = locInventTransferLineItemSet.TransactionCode;
    //clsDetailTmp.TransDate                      = locInventTransferLineItemSet.TransDate;
    clsDetailTmp.TransferId                     = locInventTransferLineItemSet.TransferId;
    clsDetailTmp.Transport                      = locInventTransferLineItemSet.Transport;
    clsDetailTmp.UnitId                         = locInventTransferLineItemSet.UnitId;
    clsDetailTmp.UnitPrice                      = locInventTransferLineItemSet.UnitPrice;
    //InventDim
    clsDetailTmp.ConfigId                       = locInventDim.ConfigId;
    clsDetailTmp.inventBatchId                  = locInventDim.inventBatchId;
    clsDetailTmp.InventColorId                  = locInventDim.InventColorId;
    clsDetailTmp.InventLocationId               = locInventDim.InventLocationId;
    clsDetailTmp.InventSerialId                 = locInventDim.InventSerialId;
    clsDetailTmp.InventSiteId                   = locInventDim.InventSiteId;
    clsDetailTmp.InventSizeId                   = locInventDim.InventSizeId;
    clsDetailTmp.InventStatusId                 = locInventDim.InventStatusId;
    clsDetailTmp.InventStyleId                  = locInventDim.InventStyleId;
    clsDetailTmp.InventVersionId                = locInventDim.InventVersionId;
    clsDetailTmp.LicensePlateId                 = locInventDim.LicensePlateId;
    clsDetailTmp.wMSLocationId                  = locInventDim.wMSLocationId;
    clsDetailTmp.wMSPalletId                    = locInventDim.wMSPalletId;
    //AVA fields
    clsDetailTmp.AVAItemSet                     = locInventTransferLineItemSet.AVAItemSet;
    clsDetailTmp.AVAItemSetCompQtyPerSerie      = locInventTransferLineItemSet.AVAItemSetCompQtyPerSerie;
    clsDetailTmp.AVAItemSetComponent            = locInventTransferLineItemSet.AVAItemSetComponent;
    clsDetailTmp.AVAItemSetExpanded             = locInventTransferLineItemSet.AVAItemSetExpanded;
    clsDetailTmp.AVAItemSetParent               = locInventTransferLineItemSet.AVAItemSetParent;
    clsDetailTmp.AVAItemSetSerie                = locInventTransferLineItemSet.AVAItemSetSerie;
    clsDetailTmp.AVAProdSchedDate               = locInventTransferLineItemSet.AVAProdSchedDate;
    clsDetailTmp.KCS_SOCPickingReleaseIndicator = locInventTransferLineItemSet.KCS_SOCPickingReleaseIndicator;
    //FurtherPostingType fields
    clsDetailTmp.QtyRemainReceive               = locInventTransferLineItemSet.QtyRemainReceive;
    clsDetailTmp.QtyRemainShip                  = locInventTransferLineItemSet.QtyRemainShip; // 2009: InventTransferJourLine.KCS_QtyRemainShip missing field
    clsDetailTmp.KCS_ModelNumber                = locNDXModelNumberHandler.nDXModelNumberFromItemId(clsDetailTmp.ItemId); // ToDo: KCS_ModelNumber?     //@NDXBase:NDXModelNumber

    clsDetailTmp.PdsCWQtyShipped                = locInventTransferLineItemSet.QtyShipped * locInventTable.NetWeight;

    clsDetailTmp.insert();
